import { Lexer } from '../../lib/marked.esm.js';
import { describe, it } from 'node:test';
import assert from 'node:assert';

function expectTokens({ md, options, tokens = [], links = {}, log = false }) {
  const lexer = new Lexer(options);
  const actual = lexer.lex(md);
  const expected = tokens;
  expected.links = links;
  if (log) {
    console.log(JSON.stringify(
      actual,
      (k, v) => v === undefined ? null : v,
      2,
    ));
  }
  assert.deepEqual(actual, expected);
}

function expectInlineTokens({ md, options, tokens, links = {} }) {
  const lexer = new Lexer(options);
  lexer.tokens.links = links;
  const outTokens = [];
  lexer.inlineTokens(md, outTokens);
  assert.deepEqual(outTokens, tokens);
}

describe('Lexer', () => {

  describe('inline', () => {
    describe('inlineTokens', () => {

      describe('url', () => {
        it('autolink', () => {
          expectInlineTokens({
            md: '<https://example.com>',
            tokens: [
              {
                type: 'link',
                raw: '<https://example.com>',
                text: 'https://example.com',
                href: 'https://example.com',
                autolink: true,
                tokens: [
                  {
                    type: 'text',
                    raw: 'https://example.com',
                    text: 'https://example.com',
                  },
                ],
              },
            ],
          });
        });

        it('autolink email', () => {
          expectInlineTokens({
            md: '<test@example.com>',
            options: {},
            tokens: [
              {
                type: 'link',
                raw: '<test@example.com>',
                text: 'test@example.com',
                href: 'mailto:test@example.com',
                autolink: true,
                tokens: [
                  {
                    type: 'text',
                    raw: 'test@example.com',
                    text: 'test@example.com',
                  },
                ],
              },
            ],
          });
        });

        it('url', () => {
          expectInlineTokens({
            md: 'https://example.com',
            tokens: [
              {
                type: 'link',
                raw: 'https://example.com',
                text: 'https://example.com',
                href: 'https://example.com',
                autolink: true,
                tokens: [
                  {
                    type: 'text',
                    raw: 'https://example.com',
                    text: 'https://example.com',
                  },
                ],
              },
            ],
          });
        });

        it('url email', () => {
          expectInlineTokens({
            md: 'test@example.com',
            options: { gfm: true },
            tokens: [
              {
                type: 'link',
                raw: 'test@example.com',
                text: 'test@example.com',
                href: 'mailto:test@example.com',
                autolink: true,
                tokens: [
                  {
                    type: 'text',
                    raw: 'test@example.com',
                    text: 'test@example.com',
                  },
                ],
              },
            ],
          });
        });
      });
    });
  });
});
